package sohal.lld.zerodha.entity;import sohal.lld.zerodha.observer.StockObserver;import java.util.ArrayList;import java.util.List;public class Stock {    private final String symbol;    private double price;    private List<StockObserver> observers;    public Stock(String symbol, double price) {        this.symbol = symbol;        this.price = price;        observers = new ArrayList<>();    }    public void addObserver(StockObserver observer) {        observers.add(observer);    }    void removeObserver(StockObserver observer) {        observers.remove(observer);    }    void notifyObservers() {        for (StockObserver observer : observers) {            observer.update(this);        }    }    public String getSymbol() {        return symbol;    }    public double getPrice() {        return price;    }    public void setPrice(double price) {        this.price = price;    }}